// Linux 202: futex — single-threaded guest; never block, satisfy musl/Qt mutex init.
long sys_futex(long uaddr, long op, long val, long timeout_ptr, long uaddr2, long val3)
{
    int cmd = (int)(op & 0x7f);

    (void)uaddr;
    (void)val;
    (void)timeout_ptr;
    (void)uaddr2;
    (void)val3;

    switch (cmd) {
    case 0: /* FUTEX_WAIT */
        /*
         * Single-threaded guest: EAGAIN makes Qt QBasicMutex / musl spin at 100% CPU
         * (futex_wait → EAGAIN → retry with no other thread ever changing *uaddr).
         * Always succeed immediately; no blocking, no EAGAIN busy-loop.
         */
        return 0;
    case 1: /* FUTEX_WAKE */
        return 1;
    case 3: /* FUTEX_REQUEUE */
    case 4: /* FUTEX_CMP_REQUEUE */
    case 5: /* FUTEX_WAKE_OP */
    case 9: /* FUTEX_WAIT_BITSET */
    case 10: /* FUTEX_WAKE_BITSET */
        return 0;
    default:
        return -22; /* EINVAL */
    }
}

